sp_widget.client_script:
api.controller = function($scope) {
    var c = this;
    c.pacoteId = '';

    c.concluir = function() {
        c.erro = null;
        c.data.action = 'concluir';
        c.data.pacoteId = c.pacoteId;
        c.server.update().then(function(r) {
            if (r.data.erro) {
                c.erro = r.data.erro;
            }
        });
    };
};

sp_widget.script:
(function() {
    var agendamentoId = options.agendamento_id || (input && input.agendamentoId);

    if (input && input.action === 'concluir') {
        try {
            new RegistrarSessaoUseCase().execute({
                agendamentoId: agendamentoId,
                pacoteId: input.pacoteId || null
            });
        } catch (e) {
            data.erro = e.message || 'Não foi possível concluir a sessão.';
        }
    }

    data.agendamento = {};
    var gr = new GlideRecord('x_espaco_agendamento');
    if (gr.get(agendamentoId)) {
        data.agendamento = {
            sys_id: gr.getUniqueValue(),
            data_hora: gr.getValue('data_hora'),
            status: gr.getValue('status'),
            penalidade: gr.getValue('penalidade') == 'true',
            cliente_nome: gr.cliente.nome.toString(),
            servico_nome: gr.servico.nome.toString(),
            profissional_nome: gr.profissional.nome.toString()
        };
    }
})();
